metadata.er-schema:
{
  "title": "looply · 订单模块 实体关系图",
  "version": "v7.0 · 2026-06-24",
  "tables": [
    {
      "name": "checkout_session",
      "comment": "结算会话",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "checkout_status",
          "comment": "状态",
          "constraint": ""
        },
        {
          "name": "address_id",
          "comment": "收货地址（如已选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "total_amount",
          "comment": "预估总金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "shipping_method",
          "comment": "配送方式（如已选）",
          "constraint": ""
        },
        {
          "name": "shipping_fee",
          "comment": "运费金额（如已选）",
          "constraint": ""
        },
        {
          "name": "parent_order_id",
          "comment": "转化的父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recovery_token",
          "comment": "恢复链接令牌",
          "constraint": "UNIQUE"
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "进入结算页创建，支付成功转化为订单，超时标记弃单"
    },
    {
      "name": "checkout_session_item",
      "comment": "结算会话商品",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "session_id",
          "comment": "所属会话（→ checkout_session）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道上架（→ listing）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "unit_price",
          "comment": "单价（快照）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "快照结算时的商品和价格，用于弃单恢复"
    },
    {
      "name": "parent_order",
      "comment": "父订单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "parent_order_no",
          "comment": "买家订单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "total_amount",
          "comment": "订单总金额（含运费税费）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "payment_ref_no",
          "comment": "支付单号（→ 支付模块）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "买家一次下单的整体订单，按商家拆分为多个子订单"
    },
    {
      "name": "order",
      "comment": "订单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_no",
          "comment": "订单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "parent_order_id",
          "comment": "所属父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "merchant_id",
          "comment": "商家（→ merchants）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_status",
          "comment": "订单状态",
          "constraint": ""
        },
        {
          "name": "subtotal_amount",
          "comment": "商品小计",
          "constraint": ""
        },
        {
          "name": "shipping_fee",
          "comment": "运费",
          "constraint": ""
        },
        {
          "name": "tax_amount",
          "comment": "税费（按收货州税率）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "address_id",
          "comment": "收货地址ID（→ address.id UUID）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recipient_first_name",
          "comment": "收件人名（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_last_name",
          "comment": "收件人姓（快照）",
          "constraint": ""
        },
        {
          "name": "recipient_name",
          "comment": "收件人全名（快照，冗余拼接）",
          "constraint": ""
        },
        {
          "name": "recipient_phone",
          "comment": "收件人电话（快照，含区号）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line1",
          "comment": "地址行1（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_address_line2",
          "comment": "地址行2（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_city",
          "comment": "城市（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_state_province",
          "comment": "州/省（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_postal_code",
          "comment": "邮编（快照）",
          "constraint": ""
        },
        {
          "name": "shipping_country_code",
          "comment": "国家编码（快照）",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "付款时间",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "交易完成时间",
          "constraint": ""
        },
        {
          "name": "cancelled_at",
          "comment": "取消时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "按商家维度拆分，发货/退款维度从 order_item 实时聚合"
    },
    {
      "name": "order_item",
      "comment": "订单商品",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "product_id",
          "comment": "实物商品（→ product）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "渠道上架（→ listing）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "item_name",
          "comment": "商品名称（快照）",
          "constraint": ""
        },
        {
          "name": "item_image",
          "comment": "商品主图（快照）",
          "constraint": ""
        },
        {
          "name": "condition_grade",
          "comment": "成色等级（快照）",
          "constraint": ""
        },
        {
          "name": "quantity",
          "comment": "数量（二手默认1）",
          "constraint": ""
        },
        {
          "name": "unit_price",
          "comment": "成交单价（快照）",
          "constraint": ""
        },
        {
          "name": "item_total",
          "comment": "小计",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "发货状态",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款状态",
          "constraint": ""
        }
      ],
      "note": "快照购买时的商品信息和价格，发货+退款双维度状态的唯一事实源"
    },
    {
      "name": "order_package",
      "comment": "订单包裹",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "tracking_no",
          "comment": "物流追踪号（→ shipments.tracking_no）",
          "constraint": ""
        },
        {
          "name": "package_status",
          "comment": "包裹状态",
          "constraint": ""
        },
        {
          "name": "shipped_at",
          "comment": "发货时间",
          "constraint": ""
        },
        {
          "name": "received_at",
          "comment": "签收时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "物理包裹，通常1订单=1包裹，装不下时拆多包裹"
    },
    {
      "name": "refund_request",
      "comment": "退款申请单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "request_no",
          "comment": "退款申请单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "refund_type",
          "comment": "退款类型",
          "constraint": ""
        },
        {
          "name": "refund_reason",
          "comment": "退款原因",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "申请退款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "approval_status",
          "comment": "审批状态",
          "constraint": ""
        },
        {
          "name": "request_channel",
          "comment": "申请渠道",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "处理人ID",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "处理人类型",
          "constraint": ""
        },
        {
          "name": "operator_note",
          "comment": "处理备注",
          "constraint": ""
        },
        {
          "name": "refund_ref_no",
          "comment": "退款单号（→ refund_order，审批通过后写入）",
          "constraint": ""
        },
        {
          "name": "requested_at",
          "comment": "申请时间",
          "constraint": ""
        },
        {
          "name": "approved_at",
          "comment": "审批通过时间",
          "constraint": ""
        },
        {
          "name": "rejected_at",
          "comment": "驳回时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "业务域：管审批决策，不管资金操作。审批通过后由支付域创建 refund_order"
    },
    {
      "name": "refund_request_item",
      "comment": "退款申请商品明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_request_id",
          "comment": "所属退款申请（→ refund_request）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_item_id",
          "comment": "订单商品（→ order_item）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "quantity",
          "comment": "退款数量",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "退款金额",
          "constraint": ""
        }
      ],
      "note": "支持部分退款，退款粒度到单件商品"
    },
    {
      "name": "refund_order",
      "comment": "退款单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_no",
          "comment": "退款单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "payment_order_id",
          "comment": "原始支付单（→ payment_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（冗余，免 join）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel",
          "comment": "退款渠道（继承原支付渠道）",
          "constraint": ""
        },
        {
          "name": "amount",
          "comment": "退款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "退款状态",
          "constraint": ""
        },
        {
          "name": "refunded_at",
          "comment": "退款到账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "支付域：管资金退回，不关心退款原因/审批。与 payment_order 对称"
    },
    {
      "name": "payment_order",
      "comment": "支付单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "payment_no",
          "comment": "支付单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "parent_order_id",
          "comment": "关联父订单（→ parent_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "买家（冗余，免 join）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel",
          "comment": "支付渠道（paypal / stripe）",
          "constraint": ""
        },
        {
          "name": "payment_method",
          "comment": "支付方式（paypal_wallet / credit_card）",
          "constraint": ""
        },
        {
          "name": "amount",
          "comment": "支付金额",
          "constraint": ""
        },
        {
          "name": "refunded_amount",
          "comment": "累计已退金额（防超额退款）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "支付单状态",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "支付成功时间",
          "constraint": ""
        },
        {
          "name": "expired_at",
          "comment": "支付超时时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "一次结算对应一笔支付单，parent_order.payment_ref_no 引用 payment_no"
    },
    {
      "name": "payment_transaction",
      "comment": "支付流水",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "transaction_no",
          "comment": "内部流水号",
          "constraint": "UNIQUE"
        },
        {
          "name": "payment_id",
          "comment": "所属支付单（→ payment_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "transaction_type",
          "comment": "交易类型（payment / refund）",
          "constraint": ""
        },
        {
          "name": "channel_transaction_id",
          "comment": "渠道交易号（对账匹配键）",
          "constraint": "UNIQUE"
        },
        {
          "name": "amount",
          "comment": "交易金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "channel_fee",
          "comment": "渠道手续费",
          "constraint": ""
        },
        {
          "name": "channel_fee_currency",
          "comment": "手续费币种",
          "constraint": ""
        },
        {
          "name": "net_amount",
          "comment": "实收/实退金额",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "流水状态",
          "constraint": ""
        },
        {
          "name": "refund_order_id",
          "comment": "关联退款单（→ refund_order，退款时）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel_raw_data",
          "comment": "渠道原始响应（JSON）",
          "constraint": ""
        },
        {
          "name": "reconciliation_status",
          "comment": "对账状态",
          "constraint": ""
        },
        {
          "name": "reconciled_at",
          "comment": "对账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "每笔资金流动（收款/退款）一条记录，对账最小粒度"
    },
    {
      "name": "user_account",
      "comment": "用户（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自登录注册模块"
    },
    {
      "name": "merchants",
      "comment": "商家（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "商家ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自主数据模块，区分自营/三方"
    },
    {
      "name": "product",
      "comment": "实物商品（外部）",
      "columns": [
        {
          "name": "product_id",
          "comment": "商品ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自商品模块，一物一件"
    },
    {
      "name": "listing",
      "comment": "渠道上架（外部）",
      "columns": [
        {
          "name": "listing_id",
          "comment": "上架ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自商品模块，渠道定价"
    }
  ],
  "relations": [
    {
      "from": "checkout_session",
      "to": "checkout_session_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#388E3C",
      "penwidth": 1.4
    },
    {
      "from": "checkout_session",
      "to": "parent_order",
      "type": "1:1",
      "label": "转化为订单",
      "color": "#388E3C",
      "penwidth": 1.4,
      "style": "dashed"
    },
    {
      "from": "parent_order",
      "to": "order",
      "type": "1:N",
      "label": "按商家拆单",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "order",
      "to": "order_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "order",
      "to": "order_package",
      "type": "1:N",
      "label": "发货包裹",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "order",
      "to": "refund_request",
      "type": "1:N",
      "label": "发起退款",
      "color": "#C0392B",
      "penwidth": 1.4
    },
    {
      "from": "refund_request",
      "to": "refund_request_item",
      "type": "1:N",
      "label": "包含商品",
      "color": "#C0392B",
      "penwidth": 1.4
    },
    {
      "from": "refund_request_item",
      "to": "order_item",
      "type": "N:1",
      "label": "关联订单商品",
      "color": "#C0392B",
      "penwidth": 1.0
    },
    {
      "from": "refund_request",
      "to": "refund_order",
      "type": "1:1",
