  "design_rules": {
    "parent_order_split": "买家一次下单按商家拆单：1 parent_order → N order（每商家一单）。支付模块以 parent_order 为单位对接，payment_ref_no 引用支付模块单号",
    "order_status_enum": "order_status 枚举：paid(已付款) / shipped(已发货) / completed(交易完成) / cancelled(已取消)。订单在支付成功后创建，起始状态即 paid。无 pending_payment 状态，支付前由 checkout_session 承载。流转：paid → shipped → completed；paid → cancelled（发货前取消）。所有包裹签收即标记 completed，无独立签收状态",
    "no_order_level_fulfillment_refund": "order 表不存 fulfillment_status 和 refund_status，发货维度和退款维度从 order_item 实时聚合查询，消除同步链路。订单列表需要「部分发货」「部分退款」筛选时，用 GROUP BY order_id + HAVING 聚合 order_item",
    "item_fulfillment_status_enum": "order_item.fulfillment_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)。这是发货维度的唯一事实源，订单级发货状态从此字段实时聚合",
    "item_refund_status_enum": "order_item.refund_status 枚举：none(无退款) / refunding(退款中) / refunded(已退款)。这是退款维度的唯一事实源，订单级退款状态从此字段实时聚合",
    "package_status_enum": "package_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)",
    "payment_ref_no_rule": "parent_order.payment_ref_no = payment_order.payment_no，是订单系统与支付系统的收款桥梁。退款桥梁：refund_request.refund_ref_no = refund_order.refund_no。两个方向均由业务域持有单号引用支付域，支付域不反向引用业务域",
    "payment_order_status_enum": "payment_order.status 枚举：pending(待支付) / succeeded(成功) / failed(失败) / closed(超时关闭)。用户跳转支付网关时创建(pending)，回调成功(succeeded)后创建 parent_order + order",
    "payment_transaction_type_enum": "transaction_type 枚举：payment(收款) / refund(退款)。每笔和支付渠道的资金流动记录一条，对账最小粒度",
    "payment_transaction_status_enum": "payment_transaction.status 枚举：pending(处理中) / succeeded(成功) / failed(失败)",
    "reconciliation_status_enum": "reconciliation_status 枚举：unreconciled(未对账) / reconciled(已对账) / discrepant(差异待处理)。对账流程：拉取渠道结算报告 → 按 channel_transaction_id 匹配 → 比对 amount/channel_fee/net_amount → 标记结果",
    "payment_refund_link": "退款资金流（业务域→支付域）：refund_request 审批通过(approved) → 调用支付系统创建 refund_order(pending) + payment_transaction(type=refund) → refund_request.refund_ref_no 写入 refund_order.refund_no → 渠道回调成功 → refund_order(succeeded) + payment_order.refunded_amount 累加 → order_item.refund_status 更新为 refunded",
    "refund_payment_decoupling": "业务域（refund_request）和支付域（refund_order）通过单号松耦合：refund_request.refund_ref_no = refund_order.refund_no，与收款方向 parent_order.payment_ref_no = payment_order.payment_no 模式对称。支付域实体不持有任何业务域 FK，保证支付系统的通用性",
    "refunded_amount_rule": "payment_order.refunded_amount 在每次 refund_order 成功时累加。创建 refund_order 前校验：refunded_amount + 本次退款 <= amount，防止超额退款。这是支付层面的兜底校验，不依赖业务层的退款申请金额汇总",
    "approval_status_enum": "refund_request.approval_status 枚举：pending(待审批) / approved(已通过) / rejected(已驳回)。只管审批决策，不管资金到账。审批通过后由支付域接管资金操作",
    "refund_order_status_enum": "refund_order.status 枚举：pending(退款中) / succeeded(退款成功) / failed(退款失败)。与 payment_order.status 对称（去掉 closed，退款无超时概念）",
    "refund_type_enum": "refund_request.refund_type 枚举：pre_shipment(发货前退款)。后续扩展退货退款时新增类型",
    "request_channel_enum": "refund_request.request_channel 枚举：email(邮件)。后续扩展自助申请时新增 app / web",
    "operator_type_enum": "refund_request.operator_type 枚举：admin(运营人员) / system(系统自动)。参考库存模块 inventory_ledger 的操作人设计模式",
    "address_snapshot": "订单创建时快照收货地址（address_id UUID + 10 个快照字段）。字段命名对齐地址模块：address_line1/state_province/postal_code。recipient_first_name + last_name 拆分存储（报关需要），recipient_name 冗余拼接用于展示。地址模块后续更新不影响已有订单",
    "price_snapshot": "order_item 在创建时快照 listing_price 为 unit_price。listing 价格变动不影响已有订单",
    "condition_snapshot": "order_item 快照 product_inspection.grade 为 condition_grade",
    "package_boundary": "订单模块用 order_package 记录「发了几个包裹」，物流模块管「怎么发」（承运商/追踪/轨迹）。跨模块关联：order_no = shipments.business_order_no（按订单维度），tracking_no = shipments.tracking_no（按包裹维度）。物流模块是独立信息服务，不直接引用订单实体",
    "order_completion_rule": "订单完成判定：所有 order_item.fulfillment_status 为 received → order_status 直接标记 completed。签收即完成，无独立签收状态",
    "status_dimension_design": "订单状态设计：order.order_status 只管生命周期（paid/shipped/completed/cancelled），发货维度和退款维度下沉到 order_item 级别（fulfillment_status + refund_status），订单级需要展示时实时聚合，不落库不同步。示例查询：部分发货订单 = 聚合 order_item 中有 shipped 且有 pending 的 order_id",
    "refund_blocks_shipping": "refund_request 审批通过(approved)后，order_item.refund_status 变为 refunding → 该商品不得发货（发货时校验 refund_status = none）。退款到账(refund_order succeeded)后变为 refunded",
    "package_simplification": "订单 = 履约作业单元（按商家拆单，未来按仓库再拆）。多包裹仅因物理尺寸约束，不做包裹-商品映射。买家视角只关心「订单有几个包裹，追踪号是什么」",
    "checkout_status_enum": "checkout_status 枚举：pending(待转化) / converted(已转化)。不设 expired 状态，不设 expired_at 字段。pending 即为弃单（进入结算但未完成转化），恢复链接有效期由业务规则（created_at + 固定时长）控制",
    "checkout_to_order_flow": "完整数据流：购物车 → 进入结算页创建 checkout_session(pending) + items 快照 → 填地址/确认商品 → 提交/去支付 → 支付成功 → checkout_session(converted) + 创建 parent_order + order + order_item",
    "checkout_abandonment": "弃单判定：checkout_status = pending 即为弃单（进入结算但未完成转化）。恢复机制：recovery_token 生成唯一恢复链接，有效期由业务规则控制（created_at + N小时）。恢复时需检查商品是否仍可购买（二手一物一件，可能已售出）",
    "cart_to_order_flow": "购物车到订单数据流：cart_item.listing_id → checkout_session_item（快照价格）→ 支付成功 → order_item（product_id + listing_id + 快照价格/成色/名称/图片）",
    "financial_model": "订单金额公式：order 实际收款 = subtotal_amount + shipping_fee + tax_amount。subtotal_amount = SUM(order_item.item_total)。parent_order.total_amount = SUM(各 order 的实际收款)。后续扩展优惠时：实际收款 = subtotal_amount + shipping_fee - discount_amount + tax_amount",
    "tax_rule": "tax_amount 按收货地址所在州的税率计算（美国各州税率不同）。税费计算在结算时由应用层完成，订单只记录结果",
    "currency_rule": "同一订单内所有金额使用相同 currency_code",
    "user_id_redundancy": "parent_order.user_id 和 order.user_id 均冗余存储买家ID，源头在 checkout_session.user_id，避免多层 join",
    "merchant_id_vs_seller_id": "商品模块用 seller_id 引用 merchants.id（卖方语境），订单模块用 merchant_id 引用同一实体（商家语境）。同一 FK 目标，不同业务语义"
  }
}
